#include "unity.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_inorder_empty_tree(void) {
    // Setup: root is NULL to trigger the path where (root != NULL) is false
    struct node* root = NULL;

    // Test: call inorder with NULL root
    // This should do nothing (no output, no crash)
    inorder(root);

    // Assertions: verify no crash occurred and root remains NULL
    TEST_ASSERT_NULL(root);
    // Since inorder prints to stdout, we could capture and assert empty output,
    // but the operation map does not provide a helper to assert empty stdout.
    // The path condition is satisfied: root != NULL is false, so the function
    // takes the implicit return path without executing any statements.
    // The test passes if it reaches this point without crashing.

    // Cleanup: nothing to free
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_inorder_empty_tree);
    return UNITY_END();
}
